mapper.select:
SELECT problem_id, bundle_sha256, testcase_version, updated_at
FROM problem_testcase_bundles
WHERE problem_id = #{problemId}

mapper.update:
UPDATE problem_testcase_bundles
SET bundle_sha256 = #{bundleSha256},
    updated_at = #{now}
WHERE problem_id = #{problemId}
  AND bundle_sha256 IS NULL
  AND testcase_version = #{testcaseVersion}
